#!/usr/bin/env python3
"""Restore a resharded directory (produced by compress.py) in place.

Usage: python decompress.py <resharded_dir>
"""
from __future__ import annotations

import gzip
import json
import multiprocessing as mp
import os
import shutil
import sys
import tarfile

MANIFEST_PREFIX = "manifest."
MANIFEST_SUFFIX = ".json.gz.part"
META_PREFIX = "__reshard_meta__"


def find_meta_dir(root):
    for name in sorted(os.listdir(root)):
        if name.startswith(META_PREFIX) and os.path.isdir(os.path.join(root, name)):
            return name
    raise SystemExit("error: no reshard metadata directory found in %s" % root)


def read_manifest(root, meta_dir):
    parts = []
    for dirpath, _dirnames, filenames in os.walk(os.path.join(root, meta_dir)):
        for name in filenames:
            if name.startswith(MANIFEST_PREFIX) and name.endswith(MANIFEST_SUFFIX):
                parts.append((name, os.path.join(dirpath, name)))
    parts.sort()
    blob = b"".join(open(p, "rb").read() for _n, p in parts)
    return json.loads(gzip.decompress(blob).decode("utf-8"))


def _extract(job):
    root, shard_rel = job
    path = os.path.join(root, shard_rel)
    with tarfile.open(path, "r:gz") as tar:
        try:
            tar.extractall(root, filter="data")
        except TypeError:  # Python < 3.12 has no filter kwarg
            tar.extractall(root)
    os.remove(path)
    return shard_rel


def main(argv):
    if len(argv) != 2:
        sys.stderr.write("Usage: python decompress.py <resharded_dir>\n")
        return 2
    root = os.path.abspath(argv[1])
    if not os.path.isdir(root):
        sys.stderr.write("error: directory not found: %s\n" % root)
        return 2

    meta_dir = find_meta_dir(root)
    manifest = read_manifest(root, meta_dir)

    for rel in manifest.get("dirs", []):
        os.makedirs(os.path.join(root, rel), exist_ok=True)

    shards = manifest.get("shards", [])
    jobs = [(root, s) for s in shards]
    try:
        ncpu = len(os.sched_getaffinity(0))
    except AttributeError:
        ncpu = os.cpu_count() or 1
    nproc = max(1, min(ncpu, len(jobs)))
    if nproc <= 1:
        for job in jobs:
            _extract(job)
    else:
        ctx = mp.get_context("fork" if "fork" in mp.get_all_start_methods() else "spawn")
        with ctx.Pool(nproc) as pool:
            for _ in pool.imap_unordered(_extract, jobs, chunksize=1):
                pass

    # reassemble files that were split into raw chunks
    for item in manifest.get("chunked", []):
        dest = os.path.join(root, item["path"])
        os.makedirs(os.path.dirname(dest) or root, exist_ok=True)
        with open(dest, "wb") as out:
            for part in item["parts"]:
                src = os.path.join(root, part)
                with open(src, "rb") as fh:
                    shutil.copyfileobj(fh, out, 1 << 20)
                os.remove(src)
        os.chmod(dest, item.get("mode", 0o644))
        mtime = item.get("mtime")
        if mtime is not None:
            os.utime(dest, (mtime, mtime))

    for name in (manifest.get("parts_dir"), manifest.get("data_dir"), meta_dir):
        if name:
            shutil.rmtree(os.path.join(root, name), ignore_errors=True)

    sys.stdout.write("restored %d files into %s\n" % (manifest.get("file_count", 0), root))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

